INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('scoa_language', '長文読解', '本格カレー作りへの挑戦', '週末、以前から気になっていた本格的なカレーのレシピに挑戦してみた。スパイスの調合や煮込み時間など、普段の手軽な料理とは勝手が違い、途中で何度も匙加減に迷った。（1）、時間をかけて丁寧に作った分だけ、いつもとは比べ物にならないほど深い味わいに仕上がった。

手間のかかる料理は面倒に感じることも多いが、じっくり向き合うことでしか得られない満足感がある。（2）、たまには効率を度外視して、時間そのものを楽しむ料理をしてみるのもよいのかもしれない。

【設問1】文中の（1）に入る接続詞として最も適切なものはどれか。', NULL, '["それでも","つまり","たとえば","なぜなら"]', 0, '["「匙加減に迷った」という苦労にもかかわらず、「深い味わいに仕上がった」という良い結果が続くため、逆接の「それでも」が適切です。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA言語分野: 長文読解・接続詞穴埋め第2弾）', 76);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('scoa_language', '長文読解', '本格カレー作りへの挑戦', '週末、以前から気になっていた本格的なカレーのレシピに挑戦してみた。スパイスの調合や煮込み時間など、普段の手軽な料理とは勝手が違い、途中で何度も匙加減に迷った。（1）、時間をかけて丁寧に作った分だけ、いつもとは比べ物にならないほど深い味わいに仕上がった。

手間のかかる料理は面倒に感じることも多いが、じっくり向き合うことでしか得られない満足感がある。（2）、たまには効率を度外視して、時間そのものを楽しむ料理をしてみるのもよいのかもしれない。

【設問2】文中の（2）に入る接続詞として最も適切なものはどれか。', NULL, '["だから","ところが","たとえば","ちなみに"]', 0, '["「じっくり向き合うことでしか得られない満足感がある」という前文を根拠として、「効率を度外視した料理をしてみるのもよい」という結論を導いているため、「だから」が適切です。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA言語分野: 長文読解・接続詞穴埋め第2弾）', 76);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('scoa_language', '長文読解', '知らない町での新生活', '先月、仕事の都合で新しい町に引っ越してきた。知り合いもおらず、土地勘もないため、最初の数週間は買い物一つするにも地図とにらめっこする日々だった。（1）、少しずつ近所を歩き回るうちに、お気に入りのパン屋や静かな公園を見つけることができた。

知らない場所での生活は不安も多いが、その分だけ新しい発見に満ちている。（2）、引っ越しは大変なことばかりではなく、自分の世界を広げるきっかけにもなるのだと思う。

【設問1】文中の（1）に入る接続詞として最も適切なものはどれか。', NULL, '["しかし","そのため","たとえば","すなわち"]', 0, '["「地図とにらめっこする日々だった」という戸惑いの状況と、「お気に入りの場所を見つけられた」という結果が対比されているため、逆接の「しかし」が適切です。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA言語分野: 長文読解・接続詞穴埋め第2弾）', 77);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('scoa_language', '長文読解', '知らない町での新生活', '先月、仕事の都合で新しい町に引っ越してきた。知り合いもおらず、土地勘もないため、最初の数週間は買い物一つするにも地図とにらめっこする日々だった。（1）、少しずつ近所を歩き回るうちに、お気に入りのパン屋や静かな公園を見つけることができた。

知らない場所での生活は不安も多いが、その分だけ新しい発見に満ちている。（2）、引っ越しは大変なことばかりではなく、自分の世界を広げるきっかけにもなるのだと思う。

【設問2】文中の（2）に入る接続詞として最も適切なものはどれか。', NULL, '["そう考えると","ところが","なぜなら","たとえば"]', 0, '["「新しい発見に満ちている」という前文の内容を根拠として、「引っ越しは自分の世界を広げるきっかけになる」という結論を導いているため、「そう考えると」が適切です。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA言語分野: 長文読解・接続詞穴埋め第2弾）', 77);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('scoa_language', '長文読解', '朝のランニング習慣', '半年前から、出勤前に近所を軽く走る習慣を始めた。最初のうちは五分も走ると息が上がり、続けられる自信がまったく持てなかった。（1）、無理のない距離から少しずつ増やしていくうちに、今では三十分ほど走っても苦しさを感じなくなった。

体力がついたことはもちろんうれしいが、それ以上に、一日を気持ちよく始められるようになったことが大きな収穫だ。（2）、早起きが苦手な人にこそ、朝の運動を試してほしいと思う。

【設問1】文中の（1）に入る接続詞として最も適切なものはどれか。', NULL, '["そこで","つまり","たとえば","なぜなら"]', 0, '["「続けられる自信がまったく持てなかった」という状況を受けて、それゆえに「無理のない距離から少しずつ増やす」という対策をとったという流れのため、順接の「そこで」が適切です。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA言語分野: 長文読解・接続詞穴埋め第2弾）', 78);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('scoa_language', '長文読解', '朝のランニング習慣', '半年前から、出勤前に近所を軽く走る習慣を始めた。最初のうちは五分も走ると息が上がり、続けられる自信がまったく持てなかった。（1）、無理のない距離から少しずつ増やしていくうちに、今では三十分ほど走っても苦しさを感じなくなった。

体力がついたことはもちろんうれしいが、それ以上に、一日を気持ちよく始められるようになったことが大きな収穫だ。（2）、早起きが苦手な人にこそ、朝の運動を試してほしいと思う。

【設問2】文中の（2）に入る接続詞として最も適切なものはどれか。', NULL, '["だからこそ","ところが","たとえば","ちなみに"]', 0, '["「一日を気持ちよく始められるようになったことが大きな収穫」という前文を踏まえて、「早起きが苦手な人にこそ試してほしい」という結論を導いているため、「だからこそ」が適切です。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA言語分野: 長文読解・接続詞穴埋め第2弾）', 78);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('scoa_language', '長文読解', '実家で見つけた古いアルバム', '実家の押し入れを整理していたら、大学時代に撮った古いアルバムが出てきた。色あせた写真を眺めていると、当時は当たり前だと思っていた友人たちとの何気ない日常が、今ではとても貴重なものだったのだと気づかされた。（1）、しばらく手を止めて、懐かしい記憶に浸ってしまった。

デジタル化が進み、紙の写真を見返す機会は少なくなった。（2）、たまにはこうして形のあるものを手に取ることで、思い出はより鮮やかによみがえるのかもしれない。

【設問1】文中の（1）に入る接続詞として最も適切なものはどれか。', NULL, '["そのため","しかし","たとえば","つまり"]', 0, '["「貴重なものだったのだと気づかされた」という内容の結果として、「手を止めて記憶に浸ってしまった」という行動が続くため、順接の「そのため」が適切です。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA言語分野: 長文読解・接続詞穴埋め第2弾）', 79);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('scoa_language', '長文読解', '実家で見つけた古いアルバム', '実家の押し入れを整理していたら、大学時代に撮った古いアルバムが出てきた。色あせた写真を眺めていると、当時は当たり前だと思っていた友人たちとの何気ない日常が、今ではとても貴重なものだったのだと気づかされた。（1）、しばらく手を止めて、懐かしい記憶に浸ってしまった。

デジタル化が進み、紙の写真を見返す機会は少なくなった。（2）、たまにはこうして形のあるものを手に取ることで、思い出はより鮮やかによみがえるのかもしれない。

【設問2】文中の（2）に入る接続詞として最も適切なものはどれか。', NULL, '["だから","とはいえ","たとえば","つまり"]', 1, '["「紙の写真を見返す機会は少なくなった」という内容の後に、「たまには手に取ることで思い出が鮮やかによみがえる」という、それに反する提案が続くため、「とはいえ」が適切です。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA言語分野: 長文読解・接続詞穴埋め第2弾）', 79);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('scoa_language', '長文読解', '初めてのオンライン読書会', '知人に誘われて、初めてオンラインの読書会に参加してみた。画面越しでのやりとりに最初は戸惑い、うまく感想を言葉にできるか不安だった。（1）、いざ話し始めてみると、同じ本を読んだ人同士だからこそ話が弾み、あっという間に一時間が過ぎていた。

一人で読書するのも良いが、誰かと感想を共有することで、自分では気づかなかった視点に出会えることもある。（2）、これからも定期的にこうした場に参加してみたいと思う。

【設問1】文中の（1）に入る接続詞として最も適切なものはどれか。', NULL, '["ところが","つまり","たとえば","なぜなら"]', 0, '["「うまく感想を言葉にできるか不安だった」という気持ちに反して、「話が弾み、あっという間に一時間が過ぎた」という予想外の展開が続くため、逆接の「ところが」が適切です。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA言語分野: 長文読解・接続詞穴埋め第2弾）', 80);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('scoa_language', '長文読解', '初めてのオンライン読書会', '知人に誘われて、初めてオンラインの読書会に参加してみた。画面越しでのやりとりに最初は戸惑い、うまく感想を言葉にできるか不安だった。（1）、いざ話し始めてみると、同じ本を読んだ人同士だからこそ話が弾み、あっという間に一時間が過ぎていた。

一人で読書するのも良いが、誰かと感想を共有することで、自分では気づかなかった視点に出会えることもある。（2）、これからも定期的にこうした場に参加してみたいと思う。

【設問2】文中の（2）に入る接続詞として最も適切なものはどれか。', NULL, '["たとえば","そのため","しかし","ちなみに"]', 1, '["「自分では気づかなかった視点に出会えることもある」という前文を根拠として、「これからも定期的に参加してみたい」という結論を導いているため、「そのため」が適切です。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA言語分野: 長文読解・接続詞穴埋め第2弾）', 80);
